MODULE T9382dffx1_Mod

    LOCAL CONST speeddata vTG001 := [4000.0,400.0,5000.0,1000.0];
    LOCAL CONST speeddata vTG002 := [775.0,500.0,5000.0,1000.0];
    LOCAL CONST zonedata zTG001 := [FALSE,25.0,37.5,37.5,3.75,37.5,3.75];

    LOCAL CONST robtarget pTG0001 := [[-1.750,0.288,-151.600],[0.882948,0.000000,0.000000,0.469472],[-1,0,-2,0],[0.000,0.000,0.000,9E9,9E9,9E9]];
    LOCAL CONST robtarget pTG0002 := [[-1.750,0.288,-1.600],[0.882948,0.000000,0.000000,0.469472],[-1,0,-2,0],[0.000,0.000,0.000,9E9,9E9,9E9]];
    LOCAL CONST robtarget pTG0003 := [[18.250,0.288,-1.600],[0.882948,0.000000,0.000000,0.469472],[-1,0,-2,0],[0.000,0.000,0.000,9E9,9E9,9E9]];
    LOCAL CONST robtarget pTG0004 := [[18.250,0.288,-151.600],[0.882948,0.000000,0.000000,0.469472],[-1,0,-2,0],[0.000,0.000,0.000,9E9,9E9,9E9]];
    LOCAL CONST jointtarget jtTG0001 := [[0.000,-30.000,40.000,0.000,90.000,0.000],[0.000,0.000,0.000,9E9,9E9,9E9]];
    LOCAL CONST jointtarget jtTG0002 := [[0.984,-10.160,38.585,-81.660,65.559,55.481],[0.000,0.000,0.000,9E9,9E9,9E9]];
    LOCAL CONST jointtarget jtTG0003 := [[-12.739,-18.518,42.630,67.510,41.663,-90.729],[0.000,0.000,0.000,9E9,9E9,9E9]];
    LOCAL CONST jointtarget jtTG0004 := [[-13.828,-18.237,42.431,67.567,42.551,-91.407],[0.000,0.000,0.000,9E9,9E9,9E9]];

    PROC T9382dffx1()
        tTG_Weld.tframe:=[[106.210,-1.030,520.250],[0.876727,0.000000,0.480989,0.000000]];
        tTG_Cam.tframe:=[[29.940,23.450,166.640],[0.491280,-0.492278,0.507015,0.509158]];
        wobjTG_Weld.uframe:=[[0,0,0],[1,0,0,0]];
        wobjTG_Weld.oframe:=[[1373.450,25.600,623.960],[0.000000,0.707107,-0.707107,0.000000]];
        wobjTG_Cam.uframe:=[[0,0,0],[1,0,0,0]];
        wobjTG_Cam.oframe:=[[0.000,0.000,0.000],[1.000000,0.000000,0.000000,0.000000]];
        TG_ActMechUnit;
        ConfL \Off;
        ConfJ \Off;
        ! Start-of-run home (SHome) NOT emitted: the HMI loads one flattened module, which declares no SHome routine.
        stTG_ProgPass:="T9382dffx1";
        stTG_RobStatus:="Ok";
        stTG_SubName:="none";
        TG_ReqPassCheck \Tool:=tTG_Weld \WObj:=wobj0;
        IF nTG_PassOK<>1 THEN
        RETURN;
        ENDIF
        TG_DryRunOff;
        IF nTG_DryRun=1 TG_DryRunOn;
        ! Capture set Captures (0.0°)
        MoveAbsJ jtTG0001, vTG001, fine, tTG_Cam;
        MoveAbsJ jtTG0002, vTG001, fine, tTG_Cam;
        stTG_SubName:="C1PGlobal_0_2";
        TG_ReqCamFrame \Tool:=tTG_Cam \WObj:=wobjTG_Cam;
        IF nTG_DoCapture=2 GOTO abort_end;
        IF nTG_DoCapture=1 THEN
        TG_CamOpen;
        WaitTime 0.20;
        TG_ReqCapture \Tool:=tTG_Cam \WObj:=wobjTG_Cam;
        IF nTG_CaptureOK=0 GOTO abort_end;
        ENDIF
        MoveAbsJ jtTG0001, vTG001, fine, tTG_Cam;
        ! End of capture set
        TG_ReqGlobalCapDone;
        TG_CamClose;
        TG_WeldPrep;
        ! Transition
        MoveAbsJ jtTG0003, vmax, fine, tTG_Weld;
        ! Start of Weld1
        stTG_SubName:="PWeld1";
        TG_ReqWeldFrame \Tool:=tTG_Weld \WObj:=wobjTG_Weld;
        TG_CamClose;
        IF nTG_WeldStatus=2 GOTO abort_end;
        IF nTG_WeldStatus=1 THEN
        IF Distance(CPos(\Tool:=tTG_Weld \WObj:=wobjTG_Weld),pTG0001.trans)>100 THEN
        TPWrite "TG ERROR: weld frame check failed - torch far from chain entry";
        GOTO abort_end;
        ENDIF
        ConfL \On;
        MoveL pTG0001, vTG002, zTG001, tTG_Weld \WObj:=wobjTG_Weld;
        MoveL pTG0002, vTG002, fine, tTG_Weld \WObj:=wobjTG_Weld;
        TG_ReqWeldParams;
        TG_ApplyWeldParams 1;
        ArcLStart pTG0003, vTG002, sdTG_Weld, wdTG_Weld, zTG001, tTG_Weld \WObj:=wobjTG_Weld;
        ArcLEnd pTG0003, vTG002, sdTG_Weld, wdTG_Weld, fine, tTG_Weld \WObj:=wobjTG_Weld;
        ! process end
        MoveL pTG0004, vTG002, fine, tTG_Weld \WObj:=wobjTG_Weld;
        ENDIF
        ! End of Weld1
        ! Transition
        MoveAbsJ jtTG0004, vmax, zTG001, tTG_Weld;
        MoveAbsJ jtTG0001, vmax, fine, tTG_Weld;
        ! Move to rest home
        TG_CamClose;
        TG_CamClose;
        abort_end:
        stTG_SubName:="none";
        TG_ReqEnd \Tool:=tTG_Weld \WObj:=wobj0;
    ENDPROC

ENDMODULE
